CREATE TABLE "environment_preview_target" (
	"id" uuid PRIMARY KEY DEFAULT uuidv7() NOT NULL,
	"workspace_id" uuid NOT NULL,
	"project_id" uuid NOT NULL,
	"environment_id" uuid NOT NULL,
	"preview_url" varchar(2048),
	"version" integer DEFAULT 1 NOT NULL,
	"created_by_user_id" text,
	"created_by_credential_id" uuid,
	"changed_by_user_id" text,
	"changed_by_credential_id" uuid,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	CONSTRAINT "environment_preview_target_environment_unique" UNIQUE("environment_id"),
	CONSTRAINT "environment_preview_target_id_tenant_unique" UNIQUE("id","workspace_id","project_id","environment_id"),
	CONSTRAINT "environment_preview_target_created_actor_exactly_one" CHECK (num_nonnulls("environment_preview_target"."created_by_user_id", "environment_preview_target"."created_by_credential_id") = 1),
	CONSTRAINT "environment_preview_target_changed_actor_exactly_one" CHECK (num_nonnulls("environment_preview_target"."changed_by_user_id", "environment_preview_target"."changed_by_credential_id") = 1),
	CONSTRAINT "environment_preview_target_preview_url_valid" CHECK ("environment_preview_target"."preview_url" is null or (octet_length("environment_preview_target"."preview_url") between 1 and 2048 and "environment_preview_target"."preview_url" = btrim("environment_preview_target"."preview_url") and "environment_preview_target"."preview_url" !~ '[[:cntrl:][:space:]?#]' and position(chr(92) in "environment_preview_target"."preview_url") = 0 and ("environment_preview_target"."preview_url" ~ '^https://[^/@]+/' or "environment_preview_target"."preview_url" ~ '^http://(localhost|127[.]0[.]0[.]1)(:[0-9]{1,5})?/' or (left("environment_preview_target"."preview_url", 12) = 'http://[::1]' and substring("environment_preview_target"."preview_url" from 13) ~ '^(:[0-9]{1,5})?/')))),
	CONSTRAINT "environment_preview_target_version_positive" CHECK ("environment_preview_target"."version" > 0)
);
